import os
import torch


class Config:
    """
    Configuration class for the Bird Species Classification task.
    Encapsulates file paths, model parameters, and training hyperparameters.
    """

    # ==========================================
    # Paths
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    # Working directory for saving checkpoints and cache
    WORKING_DIR = "./working/idea_4"

    # Metadata CSVs (Generated by metadata script)
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Data Source
    SPECTROGRAM_DIR = os.path.join(INPUT_DIR, "supplemental_data", "spectrograms")

    # Submission
    SUBMISSION_PATH = "./submission/submission.csv"

    # ==========================================
    # Data Preprocessing
    # ==========================================
    # Height 256 preserves frequency bins. Width 1280 covers ~10s at decent resolution.
    IMG_HEIGHT = 256
    IMG_WIDTH = 1280

    # Number of species
    NUM_CLASSES = 19

    # ==========================================
    # Model Architecture
    # ==========================================
    BACKBONE = "efficientnet_b0"
    PRETRAINED = True
    # Use Generalized Mean Pooling instead of GAP
    USE_GEM_POOLING = True

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    SEED = 42

    # Batch size for A100 (40GB)
    BATCH_SIZE = 16

    # Optimizer settings
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-5

    # Scheduler
    T_MAX = 50  # For CosineAnnealingLR

    # Epochs
    EPOCHS = 50

    # Augmentation
    MIXUP_ALPHA = 0.2

    # Hardware
    NUM_WORKERS = 4
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # ==========================================
    # Debugging & Flexibility
    # ==========================================
    # Set to True to train on a small subset for debugging
    DEBUG = False
    DEBUG_SUBSET_SIZE = 20

    @classmethod
    def setup(cls):
        """
        Ensures necessary directories exist.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(os.path.dirname(cls.SUBMISSION_PATH), exist_ok=True)
